// header is the first line of every generated file.
const header = "<!-- Generated by go/internal/tools/docgen. Do not edit: change the source it names, then run `go -C go run ./internal/tools/docgen -w`. -->\n\n"

// rel returns the relative link from page to target, both relative to
// the root.
func rel(page, target string) string {
	from := strings.Split(path.Dir(page), "/")
	to := strings.Split(target, "/")
	if from[0] == "." {
		from = nil
	}
	i := 0
	for i < len(from) && i < len(to)-1 && from[i] == to[i] {
		i++
	}
	return strings.Repeat("../", len(from)-i) + strings.Join(to[i:], "/")
}

// reqLinks links requirement ids to their anchors in the specification.
func reqLinks(page string, ids []string) string {
	var out []string
	for _, id := range ids {
		out = append(out, fmt.Sprintf("[%s](%s#%s)", id, rel(page, "spec/format-1.md"), strings.ToLower(id)))
	}
	return strings.Join(out, ", ")
}

// cell makes text safe for one table cell.
func cell(s string) string {
	s = strings.ReplaceAll(s, "\n\n", " ")
	s = strings.ReplaceAll(s, "\n", " ")
	return strings.ReplaceAll(s, "|", `\|`)
}

// thousands formats n with comma separators.
func thousands(n int64) string {
	s := strconv.FormatInt(n, 10)
	neg := strings.HasPrefix(s, "-")
	s = strings.TrimPrefix(s, "-")
	var b strings.Builder
	for i, r := range s {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	if neg {
		return "-" + b.String()
	}
	return b.String()
}

// formatAmount formats a default as the docs and the code comments spell
// it: binary units for bytes, separators for counts.
func formatAmount(v int64, unit string) string {
	if unit == "bytes" {
		for _, u := range []struct {
			name  string
			shift uint
		}{{"GiB", 30}, {"MiB", 20}, {"KiB", 10}} {
			if v >= 1<<u.shift && v%(1<<u.shift) == 0 {
				return fmt.Sprintf("%d %s", v>>u.shift, u.name)
			}
		}
		return thousands(v) + " bytes"
	}
	return thousands(v)
}

func (g *generator) pending(page string) string {
	if g.parity.JavaPending == "" {
		return ""
	}
	return "> Pending: Java names follow " + g.parity.JavaPending + "\n\n"
}

// goDefault returns the default Go's withDefaults sets for a Limits field.
// Derived defaults require a recognized implementation as well as a matching
// comment. TestLimitsDoc also compares the page against the running defaults.
func (g *generator) goDefault(typ, field string, derived bool) (int64, error) {
	p := g.goPkgs[""]
	if !p.defaultSet[typ][field] {
		return 0, fmt.Errorf("%s.withDefaults sets no default for %s", typ, field)
	}
	if derived {
		return p.derivedDefault(typ, field)
	}
	v, ok := p.defaults[typ][field]
	if !ok {
		return 0, fmt.Errorf("%s.%s: its default is not a constant expression docgen reads; mark it derived in limits.json", typ, field)
	}
	return v, nil
}

// limitDefault returns the default of a Limits field as the docs give it,
// and checks that the field's comment states the same amount.
func (g *generator) limitDefault(typ, field, unit string, derived bool, doc string) (string, error) {
	amount, err := g.goDefault(typ, field, derived)
	if err != nil {
		return "", err
	}
	text := formatAmount(amount, unit)
	if derived {
		p := g.goPkgs[""]
		text = fmt.Sprintf("%d × %d × `PageValues` + `PageBytes`: %s at their defaults", p.ints["optionalValueSlices"], p.ints["valueBytes"], text)
	}
	if !strings.Contains(doc, formatAmount(amount, unit)) {
		return "", fmt.Errorf("%s.%s: its comment does not state its default, %s", typ, field, formatAmount(amount, unit))
	}
	return text, nil
}

func fieldDoc(p *goPackage, typ, field string) string {
	for _, f := range p.fields[typ] {
		if f.name == field {
			return f.doc
		}
	}
	return ""
}

func (g *generator) renderLimits() (string, error) {
	const page = "docs/reference/limits.md"
	p := g.goPkgs[""]
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# Limits and caches\n\n")
	b.WriteString(g.pending(page))
	b.WriteString("These settings bound specific input sizes, decoding estimates, retained indexes and lookup row counts. They do not bound result sizes, dataset lifetime or concurrency; bound those yourself.\n")
	b.WriteString("A **limit** fails the operation that exceeds it with a limit error: Go `*LimitError`, which wraps `ErrLimitExceeded`, or Java `LimitExceededException`.\n")
	b.WriteString("A **cache budget** never fails an operation; past it, the reader evicts cached bytes or stops keeping what it loads.\n")
	fmt.Fprintf(&b, "Exceeding a limit is a policy of yours or a capacity of the reader, never a refusal of the data (%s).\n", reqLinks(page, []string{"CHECK-5"}))
	b.WriteString("A zero setting takes its default. Negative settings are rejected when Go opens the dataset or Java builds the Limits.\n\n")
	fmt.Fprintf(&b, "What to do when an operation exceeds one: [troubleshooting](%s#limits).\n\n", rel(page, "docs/guides/troubleshooting.md"))
	for _, s := range g.limits.Structs {
		fmt.Fprintf(&b, "## Settings\n\nGo sets them in `%s`; Java with `%s` methods of the same names.\n\n", s.Go, s.Java)
		b.WriteString("| Go field | Java method | Default | Kind |\n|---|---|---|---|\n")
		var details strings.Builder
		for _, f := range s.Fields {
			doc := fieldDoc(p, s.Go, f.Go)
			def, err := g.limitDefault(s.Go, f.Go, f.Unit, f.Derived, doc)
			if err != nil {
				return "", err
			}
			kind := "limit"
			if f.Kind == "cache" {
				kind = "cache budget"
			}
			java := "Go only"
			if f.Java != nil {
				java = "`" + *f.Java + "`"
			}
			fmt.Fprintf(&b, "| [`%s`](#%s) | %s | %s | %s |\n", f.Go, strings.ToLower(f.Go), java, def, kind)
			fmt.Fprintf(&details, "### `%s`\n\n%s\n\n", f.Go, doc)
		}
		b.WriteString("\n## Fixed capacities\n\nThese are capacities of the reader, not settings. Exceeding one is reported like a limit.\n\n")
		b.WriteString("| Go `LimitName` | Java `LimitName` | Capacity |\n|---|---|---|\n")
		for _, f := range g.limits.Fixed {
			fmt.Fprintf(&b, "| `%s` | `%s` | %s |\n", f.Go, f.Java, cell(f.Value))
		}
		b.WriteString("\n## Each setting\n\nThe descriptions below are Go’s accounting rules. Where a Java counterpart is listed, its numeric default matches Go's, but Java uses different decoding-memory estimates and may reject different pages. In particular, Java’s default PageMemory can reject a binary dictionary within PageBytes and PageValues.\n\n")
		b.WriteString(details.String())
	}
	return strings.TrimRight(b.String(), "\n") + "\n", nil
}

func (g *generator) renderReadStats() (string, error) {
	const page = "docs/reference/read-stats.md"
	p := g.goPkgs[""]
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# Read statistics\n\n")
	b.WriteString(g.pending(page))
	b.WriteString("Go exposes ReadStats for Rows, Get, Scan, List, Dataset.Verify, Dataset.Plan, Plan.Split and Plan.Scan. Java supplies statistics through ReadOptions, including for verify and columns. In Go, pass a `*ReadStats` as the statistics argument: it is reset when the operation starts and filled as it runs, whether the operation succeeds or fails. `Dataset.Verify(ctx, stats)` takes the same statistics argument; pass nil to discard statistics.\n")
	b.WriteString("In Java, pass a statistics consumer in `ReadOptions`; it receives a `ReadStats` record.\n\n")
	b.WriteString("For Go's open operation, set `OpenOptions.OpenStats`: it includes manifest I/O, is reset on entry to OpenDataset or OpenDir and filled on every exit. The Dataset does not retain it. Manifest reads are excluded from SourceReads and SourceBytes.\n\n")
	b.WriteString("The counts describe this reader's access path. They are diagnostics, not part of the format: another reader, or another version of this one, may do the same read with different counts.\n\n")
	b.WriteString("The table's meanings describe Go; Java differences follow it.\n\n")
	b.WriteString("| Go field | Java component | Meaning |\n|---|---|---|\n")
	java := map[string]string{}
	for _, f := range g.stats.Fields {
		if f.Java != nil {
			java[f.Go] = "`" + *f.Java + "`"
		} else {
			java[f.Go] = "Go only"
		}
	}
	for _, f := range p.fields["ReadStats"] {
		fmt.Fprintf(&b, "| `%s` | %s | %s |\n", f.name, java[f.name], cell(f.doc))
	}
	b.WriteString("\nJava's `ReadStats` Javadoc gives these differences:\n\n")
	b.WriteString("- `groupsSkipped` is always 0: Java has no shortcut that emits a whole row group as a common prefix.\n")
	b.WriteString("- `sourceReads` counts `PartSource.read` calls; Java does not batch reads. `sourceBytes` counts their requested bytes.\n")
	b.WriteString("- `indexLoads` counts successful key page index reads from storage, including build-only transient loads; there is no retained raw metadata case. An index a concurrent request published first counts as reuse, and an index refused by `indexMemory` counts in neither `indexLoads` nor `rowGroupsOpened`.\n")
	return b.String(), nil
}

// stage spells a detection stage of refusal-codes.json for people.
func stage(detect string) string {
	switch detect {
	case "open":
		return "open"
	case "touch":
		return "first touch of the part"
	case "read":
		return "read"
	}
	if level, ok := strings.CutPrefix(detect, "validate:"); ok {
		return "validation, " + level + " level"
	}
	return detect
}

// goConstFor returns the Go constant of goType with value, the first by
// name when several share it.
func (g *generator) goConstFor(goType, value string) string {
	var names []string
	for _, c := range g.goPkgs[""].consts {
		if c.typ == goType && c.value == value {
			names = append(names, c.name)
		}
	}
	sort.Strings(names)
	if len(names) == 0 {
		return ""
	}
	return names[0]
}

func (g *generator) renderRefusalCodes() (string, error) {
	const page = "docs/reference/refusal-codes.md"
	trouble := rel(page, "docs/guides/troubleshooting.md")
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# Refusal and unsupported codes\n\n")
	fmt.Fprintf(&b, "A refusal reports a violation of the [specification](%s) or an unsupported dataset version.\n", rel(page, "spec/format-1.md"))
	fmt.Fprintf(&b, "The codes are stable; the text of an error is not ([§10](%s#10-refusal-codes)).\n", rel(page, "spec/format-1.md"))
	fmt.Fprintf(&b, "The source of this page is [spec/refusal-codes.json](%s), plus the causes and actions in [docs/data/refusal-actions.json](%s).\n\n", rel(page, "spec/refusal-codes.json"), rel(page, "docs/data/refusal-actions.json"))
	b.WriteString("\"Detected\" is the latest point at which a reader must detect the fault. A reader may detect it earlier.\n\n")
	b.WriteString("## Refusal codes\n\n| Code | Meaning | Detected | What to do |\n|---|---|---|---|\n")
	for _, c := range g.codes.Codes {
		fmt.Fprintf(&b, "| [`%s`](%s#%s) | %s | %s | %s |\n", c.Code, trouble, c.Code, cell(c.Meaning), stage(c.Detect), cell(g.actions.Refusals[c.Code].Action))
	}
	b.WriteString("\n## Unsupported codes\n\nAn unsupported code reports a feature the reader does not implement. It does not certify the dataset’s validity; the reader may stop before checking other rules.\n\n")
	b.WriteString("| Code | Meaning | What to do |\n|---|---|---|\n")
	for _, c := range g.unsupportedCodes() {
		fmt.Fprintf(&b, "| [`%s`](%s#%s) | %s | %s |\n", c.Code, trouble, c.Code, cell(c.Meaning), cell(g.actions.Unsupported[c.Code].Action))
	}
	b.WriteString("\n## Codes in Go and Java\n\n")
	b.WriteString("Go reports a refusal as a `*RefusalError` whose `Code` is a `RefusalCode`; `RefusalCodeOf(err)` returns it. ")
	b.WriteString("Java throws a `RefusalException` whose `code()` is a `RefusalCode`. ")
	b.WriteString("Unsupported features are Go `*UnsupportedError` and Java `UnsupportedFeatureException`, each with an `UnsupportedCode`.\n\n")
	b.WriteString("| Code | Go constant | Java constant | Requirements |\n|---|---|---|---|\n")
	for _, c := range g.codes.Codes {
		fmt.Fprintf(&b, "| `%s` | `%s` | `RefusalCode.%s` | %s |\n", c.Code, g.goConstFor("RefusalCode", c.Code), strings.ToUpper(c.Code), reqLinks(page, c.Requirements))
	}
	for _, c := range g.unsupportedCodes() {
		fmt.Fprintf(&b, "| `%s` | `%s` | `UnsupportedCode.%s` | |\n", c.Code, g.goConstFor("UnsupportedCode", c.Code), strings.ToUpper(strings.TrimPrefix(c.Code, "unsupported_")))
	}
	b.WriteString("\n## Outcomes that are not codes\n\n| Outcome | Meaning | Go | Java |\n|---|---|---|---|\n")
	for _, n := range g.codes.NonRefusals {
		var goErr, javaErr string
		switch n.Status {
		case "invalid_request":
			goErr, javaErr = "`ErrInvalidRequest`", "`IllegalArgumentException`"
		case "unsupported":
			goErr, javaErr = "`*UnsupportedError`", "`UnsupportedFeatureException`"
		case "error":
			goErr, javaErr = "the `Source`'s error, `ErrClosed`, or the context's error", "`StorageException`, `IllegalStateException`, or `CancellationException`"
		default:
			return "", fmt.Errorf("refusal-codes.json: unknown non-refusal status %q", n.Status)
		}
		fmt.Fprintf(&b, "| %s | %s | %s | %s |\n", n.Status, cell(n.Meaning), goErr, javaErr)
	}
	b.WriteString("\nA limit exceeded is none of these: see [limits](limits.md).\n")
	return b.String(), nil
}

func symbolCell(name *string) string {
	if name == nil {
		return "—"
	}
	return "`" + strings.TrimPrefix(*name, "std:") + "`"
}

func (g *generator) renderParity() (string, error) {
	const page = "docs/reference/parity.md"
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("# Go and Java names\n\n")
	b.WriteString(g.pending(page))
	b.WriteString("The same concept under its Go and its Java name. Go names are in package `github.com/varveio/seekparquet/go` unless prefixed `write.` or `local.`; Java names are in package `io.varve.seekparquet` unless prefixed `storage.`.\n")
	b.WriteString("A dash means the language has no counterpart. Names are checked against the code by `go/internal/tools/docgen`.\n")
	for _, s := range g.parity.Sections {
		fmt.Fprintf(&b, "\n## %s\n\n| Concept | Go | Java | Note |\n|---|---|---|---|\n", s.Title)
		for _, r := range s.Rows {
			fmt.Fprintf(&b, "| %s | %s | %s | %s |\n", cell(r.Concept), symbolCell(r.Go), symbolCell(r.Java), cell(r.Note))
		}
	}
	return b.String(), nil
}

func (g *generator) renderStatus(page string) (string, error) {
	s := g.status
	if s.Status != "draft" {
		return "", fmt.Errorf("spec/status.json: status %q: the status box describes drafts only; update docgen", s.Status)
	}
	return fmt.Sprintf("> **Pre-release.** Format %d is a draft: draft revision %d, stored on disk as `format_version` %d so that a draft file is never mistaken for a final one. "+
		"The conformance suite is at revision `%s`. "+
		"The Go module and the Java reader have no release of this API yet: this documentation describes `main`, which may change before the first release. "+
		"See [compatibility](%s) for what is stable.\n",
		s.TargetFormatVersion, s.DraftRevision, s.OnDisk.FormatVersion, s.ConformanceRevision, rel(page, "docs/reference/compatibility.md")), nil
}

func (g *generator) renderTroubleRefusals(page string) (string, error) {
	var b strings.Builder
	for _, c := range g.codes.Codes {
		a := g.actions.Refusals[c.Code]
		fmt.Fprintf(&b, "### `%s`\n\n%s Detected at the latest on %s (%s).\n\n- **Usual cause:** %s\n- **What to do:** %s\n\n",
			c.Code, c.Meaning, stage(c.Detect), reqLinks(page, c.Requirements), a.Cause, a.Action)
	}
	return strings.TrimRight(b.String(), "\n") + "\n", nil
}

func (g *generator) renderTroubleUnsupported(page string) (string, error) {
	var b strings.Builder
	for _, c := range g.unsupportedCodes() {
		a := g.actions.Unsupported[c.Code]
		meaning := strings.ToUpper(c.Meaning[:1]) + c.Meaning[1:]
		fmt.Fprintf(&b, "### `%s`\n\n%s.\n\n- **Usual cause:** %s\n- **What to do:** %s\n\n", c.Code, meaning, a.Cause, a.Action)
	}
	return strings.TrimRight(b.String(), "\n") + "\n", nil
}

func (g *generator) renderTroubleLimits(page string) (string, error) {
	var b strings.Builder
	for _, s := range g.limits.Structs {
		for _, f := range s.Fields {
			if f.Kind == "cache" {
				continue
			}
			java := ""
			if f.Java != nil {
				java = fmt.Sprintf(", Java `LimitName.%s`", upperSnake(*f.Java))
			}
			fmt.Fprintf(&b, "### `%s`\n\nGo `Limit%s`%s. [Default and meaning](%s#%s).\n\n%s\n\n",
				f.Go, f.Go, java, rel(page, "docs/reference/limits.md"), strings.ToLower(f.Go), f.Action)
		}
	}
	for _, f := range g.limits.Fixed {
		fmt.Fprintf(&b, "### `%s`\n\nGo `%s`, Java `LimitName.%s`. The reader's capacity: %s.\n\n%s\n\n", f.Name, f.Go, f.Java, f.Value, f.Action)
	}
	return strings.TrimRight(b.String(), "\n") + "\n", nil
}
